new Promise<Blob>((resolve, reject) => {
    let settled = false;
    const finish = (fn: () => void) => {
      if (settled) return;
      settled = true;
      clearTimeout(timer);
      signal?.removeEventListener('abort', onAbort);
      worker.onmessage = null;
      worker.onerror = null;
      worker.terminate();
      fn();
    };
    const timer = setTimeout(
      () => finish(() => reject(new Error('Image effects worker timed out.'))),
      // Keep worker failure bounded well below the UI acceptance timeout, then use the local fallback.
      Math.max(1, Math.min(timeoutMs, 8_000)),
    );
    const onAbort = () => finish(() => reject(cancelledError()));
    signal?.addEventListener('abort', onAbort, { once: true });
    worker.onerror = () => {
      finish(() => reject(new Error('IMAGE_EFFECTS_WORKER_FAILED')));
    };
    worker.onmessage = (event: MessageEvent<{ ok: boolean; blob?: Blob; error?: string }>) => {
      const data = event.data;
      if (data?.ok && data.blob instanceof Blob && data.blob.size > 0) {
        finish(() => resolve(data.blob!));
        return;
      }
      finish(() => reject(new Error(data?.error || 'IMAGE_EFFECTS_WORKER_FAILED')));
    };
    try {
      worker.postMessage({ blob: input, effects });
    } catch (error) {
      finish(() => reject(error instanceof Error ? error : new Error('IMAGE_EFFECTS_WORKER_FAILED')));
    }
  }).catch

page.evaluate(async (duration) => {
    const canvas = document.createElement('canvas');
    canvas.width = 320;
    canvas.height = 180;
    const ctx = canvas.getContext('2d');
    if (!ctx || !window.MediaRecorder) throw new Error('VIDEO_FIXTURE_APIS_UNAVAILABLE');

    const mimeType = ['video/webm;codecs=vp8', 'video/webm'].find((type) =>
      !window.MediaRecorder?.isTypeSupported || window.MediaRecorder.isTypeSupported(type),
    );
    if (!mimeType) throw new Error('VIDEO_FIXTURE_WEBM_UNAVAILABLE');

    const stream = canvas.captureStream(15);
    const recorder = new window.MediaRecorder(stream, { mimeType });
    const chunks: Blob[] = [];
    const stopped = new Promise<void>((resolve, reject) => {
      recorder.ondataavailable = (event) => { if (event.data.size > 0) chunks.push(event.data); };
      recorder.onerror = () => reject(new Error('VIDEO_FIXTURE_RECORDING_FAILED'));
      recorder.onstop = () => resolve();
    });

    recorder.start(100);
    const started = performance.now();
    const draw = () => {
      const elapsed = performance.now() - started;
      ctx.fillStyle = '#111827';
      ctx.fillRect(0, 0, 320, 180);
      ctx.fillStyle = '#22c55e';
      ctx.fillRect(0, 0, 160, 180);
      ctx.fillStyle = '#2563eb';
      ctx.fillRect(160, 0, 160, 180);
      ctx.fillStyle = '#ffffff';
      ctx.fillRect(110 + Math.round(Math.sin(elapsed / 150) * 25), 60, 20, 60);
      if (elapsed >= duration) {
        recorder.stop();
        return;
      }
      requestAnimationFrame(draw);
    };
    draw();
    await stopped;
    stream.getTracks().forEach((track) => track.stop());

    const blob = new Blob(chunks, { type: 'video/webm' });
    const signature = Array.from(new Uint8Array(await blob.slice(0, 4).arrayBuffer()));
    if (blob.size <= 4 || signature.join(',') !== '26,69,223,163') {
      throw new Error('VIDEO_FIXTURE_SIGNATURE_INVALID');
    }
    return btoa(String.fromCharCode(...new Uint8Array(await blob.arrayBuffer())));
  }, durationMs).then
